UPDATE courses SET
    course_description = '<div id="collapseOne" class="accordion-collapse collapse show" aria-labelledby="headingOne" data-bs-parent="#accordionExample"> <div class="accordion-body"> <div class="theory-box"> <p>This qualification provides a trade outcome in wall and floor tiling for residential and commercial construction work. The qualification has a core unit of competency requirements that cover common skills for the construction industry, as well as the specialist field of work, wall and floor tiling. Tilers work with materials like ceramic, glass, slate, marble, and clay. They cut these materials and lay tiles on walls and floors, both interior and exterior. They may also add decorative touches to their basic work.</p> </div> </div> </div>',
    total_course_duration = '96 weeks',
    offshore_tuition_fee = 24000,
    onshore_tuition_fee = 24000,
    enrolment_fee = 250,
    materials_fee = 4000,
    entry_requirements = '<div id="collapseEight" class="accordion-collapse collapse" aria-labelledby="headingEight" data-bs-parent="#accordionExample"> <div class="accordion-body"> <div class="theory-box"> <p>To ensure an appropriate learning opportunity, candidates need to demonstrate a capacity to undertake study at a Cert III level, this can be demonstrated via the following:</p> <table class="table-bordered table table-hover" cellspacing="0" cellpadding="0" border="0"><tbody><tr><td><strong>English Language Requirement (International Students):</strong></td> <td>IELTS 5.5 Or equivalent PTE Academic Test Score or other equivalent English language test scores (e.g., TOEFL, ISLPR, CSWE, General English, EAP, etc).</td> </tr><tr><td><strong>Academic Level</strong></td> <td>Year 12 or equivalent high school certificate.</td> </tr><tr><td><strong>Minimum Age</strong></td> <td>18 years or over at the time of commencement.</td> </tr></tbody></table><p><strong>Note: </strong>Students who do not meet the minimum English requirement for this course will need to package this course with an appropriate English Course before they can proceed into this course/qualification.</p> <p><strong>Note: </strong>Students are expected to be physically fit in order to take this course, as it involves physical activities such as lifting materials.</p> </div> </div> </div>',
    apply_form = 'https://acmi.wa.edu.au/certificate-III-in-wall-and-floor-tiling.php',
    updated_at = NOW()
WHERE cricos_course_code = '116684C';
