UPDATE courses SET
    course_description = '<div id="collapseOne" class="accordion-collapse collapse show" aria-labelledby="headingOne" data-bs-parent="#accordionExample"> <div class="accordion-body"> <p><strong>BSB50120 Diploma of Business (Operations) </strong>This qualification reflects the role of individuals in a variety of Business Services job roles. These individuals may have frontline management accountabilities. </p> <p>Individuals in these roles carry out moderately complex tasks in a specialist field of expertise that requires business operations skills. They may possess substantial experience in a range of settings, but seek to further develop their skills across a wide range of business functions.</p> </div> </div>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = 9500,
    onshore_tuition_fee = 9500,
    enrolment_fee = 250,
    materials_fee = 500,
    entry_requirements = '<div id="collapseSix" class="accordion-collapse collapse" aria-labelledby="headingSix" data-bs-parent="#accordionExample"> <div class="accordion-body"> <p>To ensure an appropriate learning opportunity, candidates need to demonstrate a capacity to undertake study at a Diploma level, this can be demonstrated via the following: </p> <table class="table-bordered table table-hover" cellspacing="0" cellpadding="0" border="0"><tbody><tr><td><strong>English Language(International Students) </strong></td> <td>IELTS Academic 6.0 Or PTE Academic Test Score of minimum 50 in each component or others equivalent (e.g., TOEFL, ISLPR, CSWE, General English, EAP) English language test scores.</td> </tr><tr><td><strong>Academic Level </strong></td> <td>Year 12 or equivalent high school certificate </td> </tr><tr><td><strong>Minimum Age </strong></td> <td>18 years or over at the time of commencement. </td> </tr></tbody></table><p><strong>Note: </strong>Students who do not meet the minimum English requirement for this course will need to package this course with an appropriate English Course before they can proceed into this course/qualification.</p> </div> </div>',
    apply_form = 'https://acmi.wa.edu.au/certificate-in-diploma-of-business.php',
    updated_at = NOW()
WHERE cricos_course_code = '106897F';
UPDATE courses SET
    course_description = '<div id="collapseOne" class="accordion-collapse collapse show" aria-labelledby="headingOne" data-bs-parent="#accordionExample"> <div class="accordion-body"> <div class="theory-box"> <p><strong>BSB60120 Advanced Diploma of Business</strong> reflects the role of individuals in a variety of Business Services job roles. These individuals may have general management accountabilities. </p> <p>Individuals in these roles carry out complex tasks in a specialist field of expertise. They may undertake technical research and analysis and will often contribute to setting the strategic direction for a work area. </p> <p>Conversely, it may also apply to those with little or no vocational experience, but who possess sound theoretical business skills and knowledge that they would like to develop in order to create further educational and employment opportunities. </p> <p>The course covers a range of competencies essential for management processes and effective leadership in an organisation and it helps develop communication skills to support individuals and teams to meet organisational or enterprise requirements. Learners will also develop skills and knowledge in managing teams, work relationships, continuous improvement, professional development, and workplace learning. </p> </div> </div> </div>',
    total_course_duration = '52 weeks',
    offshore_tuition_fee = 9500,
    onshore_tuition_fee = 9500,
    enrolment_fee = 250,
    materials_fee = 500,
    entry_requirements = '<div id="collapseSeven" class="accordion-collapse collapse" aria-labelledby="headingSeven" data-bs-parent="#accordionExample"> <div class="accordion-body"> <div class="theory-box"> <p>To ensure an appropriate learning opportunity, candidates need to demonstrate a capacity to undertake study at Advanced Diploma level, this can be demonstrated via the following:</p> <table class="table-bordered table table-hover" cellspacing="0" cellpadding="0" border="0"><tbody><tr><td><strong>English Language(International Students) </strong></td> <td>IELTS Academic 6.0 Or PTE Academic Test Score of minimum 50 in each component or others equivalent (e.g., TOEFL, ISLPR, CSWE, General English, EAP) English language test scores.</td> </tr><tr><td><strong>Academic Level </strong></td> <td>Year 12 or equivalent high school certificate.</td> </tr><tr><td><strong>Minimum Age </strong></td> <td>18 years or over at the time of commencement. </td> </tr></tbody></table><p><b>Entry to this qualification is limited to those who:</b></p> <p style="margin-bottom: 0;">Have completed a Diploma or Advanced Diploma from the BSB Training Package (current or superseded equivalent versions).</p> <p style="margin-bottom: 0;">or</p> <p>Have two years equivalent full-time relevant workplace experience in an operational or leadership role in an enterprise.</p> <p><strong>Note: </strong>Students who do not meet the minimum English requirement for this course will need to package this course with an appropriate English Course before they can proceed into this course/qualification.</p> </div> </div> </div>',
    apply_form = 'https://acmi.wa.edu.au/certificate-in-advanced-diploma-of-business.php',
    updated_at = NOW()
WHERE cricos_course_code = '106898E';
UPDATE courses SET
    course_description = '<div id="collapseOne" class="accordion-collapse collapse show" aria-labelledby="headingOne" data-bs-parent="#accordionExample"> <div class="accordion-body"> <div class="theory-box"> <p><b>RII50520 Diploma of Civil Construction Design</b> Qualification reflects the role of individuals working as designers or design paraprofessionals who support professional engineers. They perform tasks involving a high level of autonomy and requiring the application of significant judgement in planning and determining the selection of equipment/roles/techniques for themselves and others. They are required to develop site specific work designs to ensure the implementation of the client’s site requirements. They demonstrate the application of a broad range of technical, managerial, coordination and planning skills.</p> <p>Students will learn the calculation, estimation and foundation measurement of civil construction projects. Students will also get an opportunity to establish required skill and knowledge in relation to detail drafting, technical specification and bills of the quantities for the building projects.</p> </div> </div> </div>',
    total_course_duration = '65 weeks',
    offshore_tuition_fee = 16000,
    onshore_tuition_fee = 16000,
    enrolment_fee = 250,
    materials_fee = 1000,
