UPDATE courses SET
    course_description = '<div id="collapseOne" class="accordion-collapse collapse show" aria-labelledby="headingOne" data-bs-parent="#accordionExample"> <div class="accordion-body"> <div class="theory-box"> <p>This qualification reflects the role of individuals who apply highly specialised knowledge and skills in the field of organisational learning and capability development. Individuals in these roles generate and evaluate complex ideas. They also initiate, design and execute major learning and development functions within an organisation. Typically, they would have full responsibility and accountability for the personal output and work of others. This qualification may apply to leaders and managers in an organisation where learning is used to build organisational capability. The job roles that relate to this qualification may also include RTO Manager and RTO Director. </p> <a href="https://training.gov.au/Training/Details/BSB80120" class="btn btn-success" target="_blank" rel="noreffer,noopner">FInd on training.gov.au</a> </div> </div> </div>',
    total_course_duration = '104 weeks',
    offshore_tuition_fee = 19400,
    onshore_tuition_fee = 19400,
    enrolment_fee = 250,
    materials_fee = 1000,
    entry_requirements = '<div id="collapseThree" class="accordion-collapse collapse" aria-labelledby="headingThree" data-bs-parent="#accordionExample"> <div class="accordion-body"> <div class="theory-box medical-care"> <p>To ensure an appropriate learning opportunity, student need to demonstrate a capacity to undertake study this qualification can be demonstrated via the following: </p> <p><strong>International Students </strong></p><div></div><p></p> <div class="list"> <ul><li>Completion of a recognised degree or diploma or advanced diploma or equivalent. (Any field) </li> <li>Year 12 High school </li> <li>Student must be aged 18 or older </li> <li>Upper-intermediate Level of English or </li> <li>IELTS Academic 6.0 or </li> <li>PTE Academic Test Score of minimum 50 in each component or </li> <li>Others equivalent. (e.g., TOEFL, ISLPR, CSWE, General English, EAP) English language test scores.</li> </ul></div> <p>You may be exempted to provide evidence of English Language competence if you have successfully completed below: </p> <div class="list"> <ul><li>5 years study evidence in an English-speaking country. </li> <li>At least 6 months of a Certificate IV level course in an Australian RTO. </li> <li>An English foundation course in Australia </li> </ul></div> <p><strong>Note: </strong>Student will need to meet the Department of Home Affairs (DHA) www.homeaffairs.gov.au English language requirements for student visa applications. <strong>Note:</strong> promotional options may be available. For detailed information, kindly contact your agent or the ACMi admissions team.</p> </div> </div> </div>',
    apply_form = 'https://acmi.wa.edu.au/BSB80120-graduate-diploma-of-management-learning.php',
    updated_at = NOW()
WHERE cricos_course_code = '108557K';
